if formatter.alternate() {
    let mut chain = self.chain();
    if let Some(first) = chain.next() {
        std::fmt::Write::write_fmt(formatter, format_args!("{}", first))?;
        for err in chain {
            formatter.write_str(": ")?;
            std::fmt::Write::write_fmt(formatter, format_args!("{}", err))?;
        }
