    unsafe { ErrorImpl::debug(this, formatter) }
} else {
    let errors: std::vec::Vec<_> = self.chain().collect();
    if errors.is_empty() {
        return Ok(());
    }
    std::fmt::Display::fmt(errors[0], formatter)?;
    if errors.len() > 1 {
        formatter.write_str("\n\nCaused by:\n")?;
        if errors.len() == 2 {
            formatter.write_str("    ")?;
            std::fmt::Display::fmt(errors[1], formatter)?;
        } else {
            for (i, err) in errors.iter().skip(1).enumerate() {
                formatter.write_str("    ")?;
                use core::fmt::Write;
                write!(formatter, "{}: ", i)?;
                std::fmt::Display::fmt(*err, formatter)?;
                if i + 1 < errors.len() - 1 {
                    formatter.write_str("\n")?;
                }
            }
        }
    }
    Ok(())
}

core::fmt::Debug::fmt(&self._object, formatter)?;
if let Some(bt) = &self.backtrace {
